<script setup lang="ts">
import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{resumeApi,questionApi,interviewApi,imageApi,type Resume,type QuestionSet}from'../api/modules';import{ElMessage}from'element-plus';const router=useRouter(),resumes=ref<Resume[]>([]),sets=ref<QuestionSet[]>([]),loading=ref(false),error=ref(''),recognizing=ref(false),fileInput=ref<HTMLInputElement>(),form=ref({resumeId:0,jobTitle:'',jobDescription:'',technology:'Java',difficulty:'进阶',count:8,types:['技术基础','项目深挖','场景题']});async function load(){[resumes.value,sets.value]=await Promise.all([resumeApi.list(),questionApi.list()]);if(!form.value.resumeId&&resumes.value.length)form.value.resumeId=resumes.value[0].id}async function generate(){loading.value=true;error.value='';try{await questionApi.generate(form.value);ElMessage.success('已通过 RAG 与模型生成题目');await load()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}async function start(id:number){const s=await interviewApi.create(id);router.push(`/interview/${s.sessionId}`)}async function remove(id:number){await questionApi.remove(id);await load()}function questions(s:QuestionSet){try{return JSON.parse(s.questionsJson)}catch{return[]}}function fmt(v:any){return Array.isArray(v)?v.join('；'):(v==null?'':String(v))}async function recognizeImage(file:File){if(!file.type.startsWith('image/')){ElMessage.warning('请提供图片文件');return}recognizing.value=true;error.value='';try{const r=await imageApi.extractJd(file);if(!r.text||!r.text.trim()){ElMessage.warning('没有从图片里识别到岗位信息');return}form.value.jobDescription=r.text.trim();ElMessage.success('已识别岗位 JD，请核对后使用')}catch(e){error.value=(e as Error).message}finally{recognizing.value=false}}function onPaste(e:ClipboardEvent){const items=e.clipboardData?.items;if(!items)return;for(let i=0;i<items.length;i++){const it=items[i];if(it.type&&it.type.indexOf('image/')===0){const f=it.getAsFile();if(f){e.preventDefault();recognizeImage(f);return}}}}function pickImage(){fileInput.value?.click()}function onFileChange(e:Event){const inp=e.target as HTMLInputElement;const f=inp.files?.[0];if(f)recognizeImage(f);inp.value=''}onMounted(()=>load().catch(e=>error.value=e.message))
</script>
<template><section class="page-head"><div><h2>面试题生成</h2><p>读取真实简历与 JD，经 RAG 混合检索后调用模型生成并保留来源。</p></div></section><section class="two-column question-layout"><form class="panel form-card" @submit.prevent="generate"><h3>生成配置</h3><label>选择简历<select v-model="form.resumeId" required><option v-for="r in resumes" :value="r.id">{{r.fileName}} · V{{r.versionNo}}</option></select></label><label>岗位名称<input v-model="form.jobTitle" required placeholder="如：高级 Java 工程师"/></label><label>完整岗位 JD<textarea v-model="form.jobDescription" required rows="8" placeholder="粘贴真实岗位描述；也可截图后直接 Ctrl+V 粘贴自动识别" @paste="onPaste"/><span style="display:flex;align-items:center;gap:10px;margin-top:6px"><button type="button" class="outline-button" :disabled="recognizing" @click="pickImage">{{recognizing?'识别中…':'上传图片识别 JD'}}</button><small style="color:#888">无法复制时，截图后在此框 Ctrl+V 粘贴</small></span><input ref="fileInput" type="file" accept="image/*" hidden @change="onFileChange"/></label><div class="form-grid"><label>技术方向<input v-model="form.technology" required/></label><label>难度<select v-model="form.difficulty"><option>基础</option><option>进阶</option><option>高级</option></select></label><label>题目数量<input v-model.number="form.count" type="number" min="1" max="30"/></label></div><div v-if="error" class="error-box">{{error}}</div><button class="primary-button" :disabled="loading||!resumes.length">{{loading?'正在检索与生成…':'生成个性化题目'}}</button><small v-if="!resumes.length">请先上传简历</small></form><article class="panel data-list"><div class="panel-title"><h3>已生成题目集</h3><small>{{sets.length}} 份</small></div><div v-if="!sets.length" class="empty-inline">暂无题目集</div><div v-for="s in sets" :key="s.id" class="set-card"><span><b>{{s.title}}</b><small>{{questions(s).length}} 道题 · {{s.createdAt}}</small></span><div><button @click="remove(s.id)">删除</button><button class="primary-button" @click="start(s.id)">开始练习</button></div><details><summary>查看题目与来源</summary><div v-for="(q,i) in questions(s)" :key="i" class="question-preview"><b>{{Number(i)+1}}. {{q.question}}</b><small>{{q.type}} · {{q.difficulty}} · 来源 {{q.sourceChunkIds?.join(', ')}}</small><p v-if="q.knowledgePoints?.length"><em>知识点：</em>{{fmt(q.knowledgePoints)}}</p><p v-if="q.reason"><em>出题理由：</em>{{q.reason}}</p><template v-if="q.referenceAnswer"><details class="ref-answer"><summary>参考答案</summary><p>{{fmt(q.referenceAnswer)}}</p><p v-if="q.scoringRubric"><em>评分要点：</em>{{fmt(q.scoringRubric)}}</p></details></template></div></details></div></article></section></template>
